const labels:Record<string,string>={all:'All saves',projects:'My artwork',favorites:'Favorite pages',starred:'Starred',recent:'Recently opened',unfiled:'Not on a board','in-progress':'In progress',finished:'Finished',archived:'Archive',trash:'Trash'};
