const bytes=(n:number)=>n>1048576?`${(n/1048576).toFixed(1)} MB`:n>1024?`${Math.ceil(n/1024)} KB`:`${n} bytes`;
const fullDate=(n:number)=>new Date(n).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'});
function relative(n:number){const diff=Date.now()-n;if(diff<60000)return'just now';if(diff<3600000)return`${Math.floor(diff/60000)} min ago`;if(diff<86400000)return`${Math.floor(diff/3600000)} hr ago`;if(diff<604800000)return`${Math.floor(diff/86400000)} days ago`;return new Date(n).toLocaleDateString();}
function node<K extends keyof HTMLElementTagNameMap>(tag:K,text?:string,className?:string){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(className)e.className=className;return e;}
function icon(name:string){const s=node('span',undefined,'aw-icon');s.innerHTML=libraryIcon(name);return s;}
function art(name:string){const s=node('span',undefined,'aw-art');s.innerHTML=boardArt(name);return s;}
function button(label:string,action:string,key?:string,ico?:string,className=''){const b=node('button',undefined,className);b.type='button';b.dataset.aw=action;if(key)b.dataset.key=key;if(ico)b.append(icon(ico));b.append(node('span',label));return b;}
function link(label:string,href:string,ico?:string,className=''){const a=node('a',undefined,className);a.href=href;if(ico)a.append(icon(ico));a.append(node('span',label));return a;}
function field(label:string,input:HTMLElement){const l=node('label',undefined,'aw-field');l.append(node('span',label),input);return l;}
function textInput(value='',max=120){const e=node('input');e.type='text';e.value=value;e.maxLength=max;return e;}
function select(options:Array<[string,string]>,value:string){const e=node('select');for(const[v,label]of options){const o=node('option',label);o.value=v;o.selected=v===value;e.append(o);}return e;}
function checkbox(label:string,checked=false){const l=node('label',undefined,'aw-check');const input=node('input');input.type='checkbox';input.checked=checked;l.append(input,node('span',label));return{label:l,input};}
function safeSlug(value:string){return/^[a-z0-9-]{1,160}$/.test(value);}
