  if(item.project){const {lineMask,compose}=await import('../studio/render');const p=await getProject(item.id);if(!p)throw new Error('This artwork is no longer available.');const source=await loadSource(p.source.blob),mask=lineMask(source,p.source.width,p.source.height,p.source.hasBrandFooter),canvas=compose(p,mask);return new File([await canvasBlob(canvas,type,.94)],`${safeFilename(p.title)}.${type==='image/png'?'png':'webp'}`,{type});}
  const res=await fetch(`/api/catalog/${encodeURIComponent(item.id)}`);if(!res.ok)throw new Error('The original page is unavailable.');const data=await res.json(),content=data.item||data,path=content.downloads?.webp;if(typeof path!=='string'||!path.startsWith('/api/download/'))throw new Error('The original image is unavailable.');const image=await fetch(path);if(!image.ok||image.headers.get('Content-Type')?.split(';')[0]!=='image/webp')throw new Error('The image could not be downloaded.');return new File([await image.blob()],`${safeFilename(item.title)}.webp`,{type:'image/webp'});
