 async function storageDetails(){const wrap=node('div',undefined,'aw-storage'),estimate=await navigator.storage?.estimate?.().catch(()=>undefined),persisted=await navigator.storage?.persisted?.().catch(()=>false);wrap.append(node('p',`${items.filter(i=>i.kind==='project').length} saved artworks · ${items.filter(i=>i.kind==='favorite').length} favorite pages · ${state.boards.length} boards`),node('p',`Artwork image files: ${bytes(items.reduce((n,i)=>n+i.bytes,0))}. Layer and undo data use additional browser storage.`));if(estimate)wrap.append(node('p',`This origin uses approximately ${bytes(estimate.usage||0)} of the browser's estimated ${bytes(estimate.quota||0)} quota.`));wrap.append(node('p',persisted?'Your browser has granted persistent storage.':'Your browser may clear storage under pressure. Download a backup for anything important.'),node('p',state.lastBackupAt?`Last library backup: ${fullDate(state.lastBackupAt)}`:'No library backup has been downloaded from this browser yet.'));const history=checkbox('Include undo history in the backup',true);history.input.dataset.backupHistory='true';wrap.append(history.label,button('Download full library backup','backup-dialog',undefined,'download','aw-primary'),button('Import a backup','import',undefined,'upload'),button('Ask browser to keep local storage','persist',undefined,'lock'),button('Export library index (CSV)','csv',undefined,'notes'));popup('Storage & backup',wrap);}
 async function previewImport(file:File){message('Checking backup files and checksums…');if(file.size>64*1024*1024)throw new Error('Choose a backup smaller than 64 MB.');const data=await readBackup(file);for(const p of data.projects){const img=await loadSource(p.source.blob);if(img.naturalWidth!==p.source.width||img.naturalHeight!==p.source.height)throw new Error('An image does not match its saved dimensions. No artwork was imported.');}importCandidate=data;const wrap=node('div');wrap.append(node('p',`This backup contains ${data.projects.length} editable artworks, ${data.favorites.length} favorite pages and ${data.library.boards.length} boards.`),node('p',`Created: ${data.createdAt?fullDate(data.createdAt):'Unknown'}`),node('p','Artwork and boards are imported as new copies. Existing artwork is never overwritten. Favorite pages already saved on this device are kept.'),button('Import as new copies','confirm-import',undefined,'upload','aw-primary'));popup('Review your backup',wrap);message('Backup verified. Review the import before adding it.');}
 async function applyImport(){const data=importCandidate;if(!data)return;if(state.boards.length+data.library.boards.length>200)throw new Error('This import would exceed the 200-board limit. Export fewer boards or remove unused boards first.');const remap=new Map<string,string>(),boardMap=new Map<string,string>();const projects=data.projects.map(p=>{const copy=structuredClone(p),old=`project:${copy.id}`;copy.id=crypto.randomUUID();remap.set(old,`project:${copy.id}`);return copy;});const favorites=data.favorites.filter(f=>{remap.set(`favorite:${f.id}`,`favorite:${f.id}`);return!items.some(i=>i.key===`favorite:${f.id}`);});for(const b of data.library.boards)boardMap.set(b.id,crypto.randomUUID());await addImportedItems(projects,favorites);await update(s=>{for(const b of data.library.boards)s.boards.push({...b,id:boardMap.get(b.id)!,name:`${b.name} · imported`.slice(0,80),cover:b.cover?remap.get(b.cover) as ItemKey:undefined,order:s.boards.length});for(const[old,m]of Object.entries(data.library.items)){const key=remap.get(old);if(!key)continue;const imported={...m,boards:m.boards.map(id=>boardMap.get(id)!).filter(Boolean)};if(s.items[key])s.items[key].boards=[...new Set([...s.items[key].boards,...imported.boards])];else s.items[key]=imported;}},false);close();await load();message(`Imported ${projects.length} artworks and ${favorites.length} new favorites. Existing work was preserved.`);}
 function archivedBoards(){const wrap=node('div');const boards=state.boards.filter(b=>b.archivedAt);if(!boards.length)wrap.append(node('p','No archived boards.'));for(const b of boards){const row=node('div',undefined,'aw-archived-board');row.append(art(b.icon),node('strong',b.name),button('Restore board','archive-board',b.id,'undo'),button('Edit','edit-board',b.id,'settings'));wrap.append(row);}popup('Archived boards',wrap);}
