 async function csv(){const rows=[['Title','Type','Saved','Created','Status','Priority','Rating','Tags','Boards','Notes'],...visible.map(i=>{const m=getMeta(i.key);return[i.title,i.kind,new Date(i.updatedAt).toISOString(),new Date(i.createdAt).toISOString(),m.status,m.priority,String(m.rating),m.tags.join('; '),m.boards.map(id=>state.boards.find(b=>b.id===id)?.name||'').join('; '),m.notes];})];const safe=(text:string)=>`"${(/^[=+\-@\t\r]/.test(text)?"'":'')+text.replaceAll('"','""')}"`;downloadBlob(new Blob(['\uFEFF'+rows.map(row=>row.map(safe).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'jotcoloring-library-index.csv');message('Library index exported. This CSV is an index, not an editable artwork backup.');}
 async function action(name:string,key:string,target:HTMLElement){
  if(name==='close-dialog'){close();return;}if(name==='scope'){setScope(target.dataset.scope||'all');return;}if(name==='open-board'){setScope(`board:${key}`);return;}if(name==='new-board'){await boardForm();return;}if(name==='edit-board'){await boardForm(state.boards.find(b=>b.id===key));return;}if(['pin-board','duplicate-board','merge-board','export-board','board-up','board-down','archive-board','delete-board'].includes(name)){await boardAction(name,key);return;}if(name==='board-settings'){const b=currentBoard();if(b)await boardForm(b);return;}if(name==='archived-boards'){archivedBoards();return;}
  if(name==='preview'){await preview(key);return;}if(name==='details'){await itemDetails(key);return;}if(name==='rename'){await rename(key);return;}if(name==='assign'||name==='move'){assign([key],name==='move');return;}if(name==='duplicate'){await duplicate(key);return;}
  if(name==='star'){await changeItems([key],m=>m.starred=!m.starred);message('Star updated.');return;}if(name==='archive'){await changeItems([key],m=>m.archivedAt=m.archivedAt?undefined:Date.now());message('Archive updated. You can undo this change.');return;}if(name==='trash'){await changeItems([key],m=>m.trashedAt=Date.now());close();message('Moved to trash. Restore it there or choose Undo.');return;}if(name==='restore'){await changeItems([key],m=>m.trashedAt=undefined);close();message('Restored from trash.');return;}
  if(name==='delete'){const item=getItem(key);if(!item||!getMeta(key).trashedAt)return;confirm('Permanently delete this save?',`“${item.title}” will be removed from this browser. This cannot be undone. Download an editable backup first if you want to keep it.`,async()=>{if(item.kind==='project')await deleteProject(item.id);else await deleteFavorite(item.id);await update(s=>{delete s.items[key];for(const b of s.boards)if(b.cover===key)b.cover=undefined;s.past=[];s.future=[];},false);await load();message('Save permanently deleted.');},'Delete permanently');return;}
  if(name==='move-up'||name==='move-down'){const index=visible.findIndex(i=>i.key===key),next=index+(name==='move-up'?-1:1);if(next<0||next>=visible.length){message('This save is already at the edge.');return;}const ordered=[...visible];[ordered[index],ordered[next]]=[ordered[next],ordered[index]];await update(s=>{ordered.forEach((i,n)=>(s.items[i.key]??=defaultMeta()).order=n);s.preferences.sort='manual';});filters.sort='manual';render();return;}
  if(name==='download-pdf'||name==='download-image'){await downloadItem(key,name==='download-pdf'?'pdf':'webp');return;}if(name==='share'){await share(key);return;}if(name==='copy-link'){const item=getItem(key);if(item){await copyText(await originalLink(item));message('Copied the original collection page link. Saved colors stay on this device.');}return;}if(name==='copy-details'){const item=getItem(key);if(item){const m=getMeta(key);await copyText(`${item.title}\nSaved: ${fullDate(item.updatedAt)}\nStatus: ${statusNames[m.status]}\nTags: ${m.tags.join(', ')}\n${m.notes}`);}return;}if(name==='view-source'){const item=getItem(key);if(item)location.assign(await originalLink(item));return;}
  if(name==='export-one'){await exportSelection([key]);return;}if(name==='export-view'){await exportSelection(visible.map(i=>i.key));return;}if(name==='backup-all'){await exportSelection(items.map(i=>i.key),true,true);return;}if(name==='backup-dialog'){await exportSelection(items.map(i=>i.key),dialog.querySelector<HTMLInputElement>('[data-backup-history]')?.checked!==false,true);return;}if(name==='csv'){await csv();return;}
  if(name==='import'){el<HTMLInputElement>('[data-aw-import]').click();return;}if(name==='confirm-import'){await applyImport();return;}if(name==='storage'){await storageDetails();return;}if(name==='persist'){const result=await navigator.storage?.persist?.();message(result?'Persistent storage granted by this browser.':'Your browser did not grant persistent storage. Download a backup to keep a copy.');return;}
  if(name==='undo'||name==='redo'){await update(s=>{(name==='undo'?undoLibrary:redoLibrary)(s);},false);message(name==='undo'?'Organization change undone.':'Organization change redone.');return;}if(name==='display'){displaySettings();return;}if(name==='shortcuts'){shortcuts();return;}if(name==='refresh'){await load();message('Library refreshed.');return;}
  if(name==='filters'){const panel=el('[data-aw-filters]')||el('#aw-filters');panel.hidden=!panel.hidden;target.setAttribute('aria-expanded',String(!panel.hidden));return;}if(name==='reset-filters'){filters={...DEFAULT_FILTERS,scope:filters.scope,sort:filters.sort};el<HTMLInputElement>('[data-aw-search]').value='';for(const e of root!.querySelectorAll<HTMLInputElement|HTMLSelectElement>('[data-aw-filter]'))e.value=String(filters[e.dataset.awFilter as keyof typeof filters]);render();return;}if(name==='clear-search'){filters.q='';el<HTMLInputElement>('[data-aw-search]').value='';el<HTMLInputElement>('[data-aw-search]').focus();render();return;}if(name==='tag-filter'){filters.tag=target.dataset.tag||'';el<HTMLSelectElement>('[data-aw-filter=tag]').value=filters.tag;el('#aw-filters').hidden=false;render();return;}
  if(name==='layout'){await update(s=>s.preferences.layout=target.dataset.layout as Preferences['layout'],false);return;}if(name==='select-mode'){selectMode=!selectMode;if(!selectMode)selected.clear();renderCards();renderBulk();return;}if(name==='select-all'){visible.forEach(i=>selected.add(i.key));selectMode=true;renderCards();renderBulk();return;}if(name==='invert-selection'){for(const i of visible)if(selected.has(i.key))selected.delete(i.key);else selected.add(i.key);renderCards();renderBulk();return;}if(name==='selection-clear'||name==='exit-selection'){selected.clear();if(name==='exit-selection')selectMode=false;renderCards();renderBulk();return;}if(name==='bulk-apply'){await bulk();return;}
 }
